.create materialized-view mv_NormalizedUsage on table RawTelemetry {
    RawTelemetry
    | extend Payload = parse_json(RawJson)
    | extend NormalizedDeviceId = toupper(extract("DEV-([0-9]+)", 1, tostring(Payload.device)))
    | summarize count() by NormalizedDeviceId
}

.alter table CuratedTelemetry policy update @'[{
  "IsEnabled": true,
  "Source": "RawTelemetry",
  "Query": "TransformTelemetry()",
  "IsTransactional": true
}]'

.create materialized-view HourlyMetrics on table DeviceTelemetry
{
    DeviceTelemetry
    | summarize AvgTemp = avg(Temperature), MaxTemp = max(Temperature), Count = count()
      by DeviceID, bin(Timestamp, 1h)
}

